# -*- coding: utf-8 -*-
"""치과 용어사전 1차 60개 — 시화점용으로 새로 작성(안산점 사전과 문장·구조가 다름).
형식: 한 줄 정의 / 쉽게 말하면 / 시화점에서는 / 자주 묻는 질문 1 / 관련 용어. 약물명·장비명·가격 없음."""
import html
def esc(s): return html.escape(s, quote=True)

def D(slug, term, cat, en, one, easy, here, q, a, rel, page=None, aliases=()):
    return dict(slug=slug, term=term, cat=cat, en=en, one=one, easy=easy, here=here, faq=(q,a), rel=list(rel), page=page, aliases=list(aliases))

TERMS = [
# 임플란트
D('implant','임플란트','임플란트','Dental implant','빠진 치아 자리의 잇몸뼈에 인공 뿌리를 심고 그 위에 치아를 올리는 치료.','나무를 심듯 뼈에 뿌리를 먼저 심고, 뿌리가 자리를 잡으면 그 위에 치아 모양을 얹는 방식입니다. 옆 치아를 깎지 않는 것이 브릿지와 다른 점입니다.','CT로 뼈와 신경 위치를 확인한 뒤 가능한 방법과 기간을 먼저 설명드립니다. 수술이 두려운 분께는 의식하진정법을 안내할 수 있습니다.','임플란트는 한 번 하면 평생 쓰나요?','영구적이라고 말씀드릴 수는 없습니다. 주변 잇몸 관리와 정기 검진에 따라 사용 기간이 달라집니다.',['픽스처','어버트먼트','골유착','뼈이식'],'implant.html',['인공치아','치아 임플란트']),
D('fixture','픽스처(고정체)','임플란트','Fixture','임플란트에서 잇몸뼈 안에 심는 인공 뿌리 부분.','임플란트는 세 부분으로 나뉘는데, 그중 뼈 속에 들어가 보이지 않는 나사 모양 부분이 픽스처입니다.','픽스처의 길이와 굵기는 뼈의 양에 맞춰 정하며, 어떤 것을 쓰는지 상담에서 설명드립니다.','픽스처는 몸에 해롭지 않나요?','대개 티타늄 계열 재료로 만들어 뼈와 잘 붙는 성질이 있습니다. 금속 알레르기가 있으면 미리 말씀해 주세요.',['임플란트','어버트먼트','골유착'],'implant.html'),
D('abutment','어버트먼트(지대주)','임플란트','Abutment','픽스처와 치아(크라운)를 연결하는 기둥 부분.','뼈 속 뿌리(픽스처)와 눈에 보이는 치아 사이를 잇는 중간 연결 기둥입니다.','뼈와 붙은 뒤 연결하며, 이 단계에서 잇몸 모양을 함께 정리합니다.','어버트먼트는 언제 연결하나요?','픽스처가 뼈와 단단히 붙은 것을 확인한 뒤 연결합니다. 보통 몇 달 뒤입니다.',['픽스처','임플란트','임시 치아'],'implant.html'),
D('osseointegration','골유착','임플란트','Osseointegration','심은 픽스처가 잇몸뼈와 단단히 붙는 과정.','뼈가 픽스처 표면을 감싸며 자라 붙는 것으로, 임플란트가 힘을 받을 수 있게 되는 핵심 단계입니다.','이 기간에는 그 자리에 힘이 실리지 않도록 식사를 조심하셔야 하며, 기간은 뼈 상태에 따라 다릅니다.','골유착이 안 되면 어떻게 되나요?','드물지만 붙지 않으면 픽스처를 제거하고 뼈가 아문 뒤 다시 심는 것을 고려합니다. 흡연과 조절되지 않는 당뇨는 영향을 줄 수 있습니다.',['픽스처','초기 고정','임플란트'],'implant.html'),
D('alveolar-bone','잇몸뼈(치조골)','임플란트','Alveolar bone','치아 뿌리를 둘러싸고 잡아 주는 턱뼈 부분.','치아를 받치는 땅에 해당합니다. 치아가 빠지거나 잇몸질환이 오래되면 이 뼈가 줄어듭니다.','임플란트 전에 CT로 뼈의 높이와 두께를 재고, 부족하면 뼈이식을 함께 계획합니다.','잇몸뼈는 다시 자라나요?','한 번 줄어든 뼈가 저절로 돌아오지는 않습니다. 필요하면 뼈이식으로 보강합니다.',['뼈이식','상악동 거상술','치주염'],'implant.html'),
D('bone-graft','뼈이식(골이식)','임플란트','Bone graft','임플란트를 심기에 뼈가 부족할 때 뼈 재료를 넣어 보강하는 시술.','땅이 얕으면 흙을 더 채우듯, 부족한 뼈 자리에 뼈 재료를 넣어 뼈가 자라도록 돕는 과정입니다.','임플란트와 같은 날 하기도 하고, 먼저 하고 기다리기도 합니다. 어느 쪽인지는 검사 후 설명드립니다.','뼈이식을 하면 기간이 얼마나 늘어나나요?','범위에 따라 다르며, 뼈가 자리 잡기를 기다리는 몇 달이 더 걸릴 수 있습니다.',['잇몸뼈','상악동 거상술','임플란트'],'implant.html'),
D('sinus-lift','상악동 거상술','임플란트','Sinus lift','위턱 어금니 쪽 빈 공간(상악동) 바닥을 올려 뼈를 만드는 시술.','위턱 어금니 위에는 코와 연결된 빈 공간이 있어 뼈가 얇은 경우가 많습니다. 그 바닥막을 살짝 들어 올리고 뼈 재료를 넣는 방법입니다.','위턱 어금니 임플란트 전에 CT로 상악동 위치를 확인하고 필요 여부를 설명드립니다.','상악동 거상술은 많이 아픈가요?','마취 후 진행하며, 시술 후 며칠간 붓거나 코 쪽이 불편할 수 있습니다. 코를 세게 푸는 것은 피해야 합니다.',['뼈이식','잇몸뼈','임플란트'],'implant.html'),
D('primary-stability','초기 고정','임플란트','Primary stability','픽스처를 심은 직후, 뼈와 붙기 전에 기계적으로 단단히 고정된 정도.','나사를 나무에 박았을 때 흔들리지 않고 꽉 잡히는 느낌에 해당합니다. 이 값이 충분해야 즉시로딩을 고려할 수 있습니다.','수술 중 고정력을 측정하고, 조건에 맞지 않으면 즉시로딩을 하지 않고 기다리는 방법으로 진행합니다.','초기 고정이 약하면 실패인가요?','아닙니다. 고정이 약하면 뼈와 붙을 시간을 충분히 기다리는 방법으로 진행합니다.',['골유착','즉시로딩','픽스처'],'immediate-loading.html'),
D('immediate-placement','즉시 식립','임플란트','Immediate placement','치아를 뺀 그날 같은 자리에 바로 임플란트를 심는 방법.','발치와 식립을 한 번에 하는 것으로, 뼈가 아물기를 기다리는 기간을 줄일 수 있습니다. 즉시로딩(바로 치아 연결)과는 다른 말입니다.','발치 자리에 염증이 없고 뼈가 충분할 때 고려하며, 검사 후 가능 여부를 설명드립니다.','즉시 식립과 즉시로딩은 같은 건가요?','다릅니다. 즉시 식립은 "빼고 바로 심는 것", 즉시로딩은 "심고 바로 임시 치아를 연결하는 것"입니다.',['즉시로딩','발치 후 주의사항','임플란트'],'implant.html'),
D('immediate-loading','즉시로딩(즉시 부하)','임플란트','Immediate loading','임플란트를 심은 당일 또는 며칠 안에 임시 치아를 연결하는 방법.','보통은 뼈와 붙을 때까지 치아 없이 기다리지만, 조건이 맞으면 임시 치아를 먼저 올려 그 기간의 불편을 줄입니다. 최종 치아는 나중에 따로 만듭니다.','모든 분께 적용되는 방법이 아니며, 초기 고정·뼈 상태·맞물림·습관을 보고 수술 중에 판단합니다.','즉시로딩이면 당일 식사가 되나요?','임시 치아 기간에는 딱딱하거나 질긴 음식을 피해야 합니다.',['초기 고정','즉시 식립','임시 치아'],'immediate-loading.html',['당일 임플란트']),
D('guided-surgery','네비게이션 임플란트(가이드 수술)','임플란트','Guided implant surgery','CT와 구강 스캔으로 위치를 미리 계획하고 가이드(틀)에 맞춰 임플란트를 심는 방법.','내비게이션으로 길을 정해 두고 가듯, 심을 위치·각도·깊이를 컴퓨터로 정한 뒤 그대로 심도록 돕는 틀을 씁니다.','신경이나 상악동과 가까운 자리, 여러 개를 한 번에 심는 경우에 권하며, 뼈가 매우 부족하면 적용이 어려울 수 있습니다.','네비게이션이면 무조건 안 아픈가요?','통증을 없애는 방법은 아닙니다. 계획대로 심기 위한 방법이며, 절개 범위가 줄어드는 경우가 있습니다.',['CT 검사','임플란트','초기 고정'],'implant-navigation.html'),
D('ct-scan','CT 검사(치과 CT)','임플란트','Cone-beam CT','턱뼈와 치아를 입체로 찍어 뼈의 양, 신경·상악동 위치를 확인하는 검사.','일반 엑스레이가 평면 사진이라면 CT는 입체 사진입니다. 임플란트 위치를 정하거나 사랑니와 신경의 거리를 볼 때 씁니다.','임플란트, 매복 사랑니, 뼈 상태 확인이 필요할 때 촬영하며, 결과를 화면으로 함께 보며 설명드립니다.','CT는 방사선이 많지 않나요?','치과 CT는 의료용 CT보다 적은 선량으로 찍도록 설계되어 있습니다. 필요한 경우에만 촬영합니다.',['네비게이션 임플란트','하치조신경','임플란트'],'implant.html'),
# 풀아치
D('full-arch','풀아치 임플란트','풀아치·틀니','Full-arch implant','위 또는 아래 치아가 대부분 없을 때 여러 개의 임플란트로 전체 치아를 고정하는 치료.','치아 하나하나를 심는 대신, 4~6개 안팎의 임플란트를 기둥처럼 세우고 그 위에 전체 치아를 다리처럼 얹습니다.','고정식과 오버덴처 중 어느 쪽이 맞는지, 남은 치아를 어떻게 할지를 검사 결과를 보고 설명드립니다. 바로드림의 시니어 풀아치 프로그램 이름은 시니올입니다.','풀아치는 임플란트를 몇 개 심나요?','뼈 상태와 설계에 따라 다르며, 흔히 4~6개 안팎입니다.',['All-on-4','오버덴처','무치악'],'implant-all-on-x.html',['전악 임플란트','올온엑스']),
D('all-on-4','All-on-4(올온포)','풀아치·틀니','All-on-4','임플란트 4개로 한 악 전체 치아를 고정하는 풀아치 방법.','네 개의 기둥 위에 전체 치아를 얹는 방식으로, 뒤쪽 임플란트를 비스듬히 심어 뼈이식을 줄이는 설계가 많습니다.','뼈 상태에 따라 4개가 맞는지, 더 필요한지 설계 단계에서 설명드립니다.','4개면 충분한가요?','뼈 상태와 씹는 힘에 따라 다릅니다. 검사 후 개수를 정합니다.',['풀아치 임플란트','오버덴처'],'implant-all-on-x.html'),
D('overdenture','오버덴처(임플란트 틀니)','풀아치·틀니','Overdenture','임플란트 몇 개에 틀니를 걸어 고정하는 방법.','틀니가 잇몸 위에서 움직이지 않도록 똑딱단추처럼 임플란트에 끼워 쓰는 틀니입니다. 뺐다 끼우는 것은 같습니다.','고정식 풀아치가 어려운 분, 수술을 줄이고 싶은 분께 설명드립니다. 아래턱은 두 개부터 시작하는 경우가 많습니다.','오버덴처도 잠잘 때 빼나요?','네. 틀니처럼 빼서 세척하고 보관합니다.',['완전틀니','풀아치 임플란트'],'denture.html'),
D('edentulous','무치악','풀아치·틀니','Edentulous','위 또는 아래턱에 치아가 하나도 없는 상태.','치아가 전부 빠진 상태를 가리키는 말입니다. 이때 선택지는 완전틀니, 오버덴처, 고정식 풀아치입니다.','뼈 상태와 생활 습관, 관리 가능 여부를 함께 보고 어느 방법이 맞는지 설명드립니다.','치아가 없으면 뼈가 계속 줄어드나요?','치아가 없는 자리는 뼈가 서서히 줄어드는 경향이 있어, 시간이 갈수록 임플란트가 어려워질 수 있습니다.',['완전틀니','오버덴처','풀아치 임플란트'],'denture.html'),
D('provisional','임시 치아(임시 보철)','풀아치·틀니','Provisional restoration','최종 치아를 만드는 동안 끼우는 임시 치아.','본을 뜨고 완성까지 기다리는 동안 모양과 기능을 유지하려고 쓰는 가치아입니다. 재료가 약해 조심해서 써야 합니다.','임시 치아 기간에 식사 방법을 안내드리고, 떨어지면 바로 내원하시도록 말씀드립니다.','임시 치아가 떨어지면 어떻게 하나요?','버리지 말고 가져오셔서 다시 붙입니다. 오래 두면 치아가 움직여 최종 치아가 안 맞을 수 있습니다.',['크라운','즉시로딩','브릿지'],'crown.html'),
# 진정·마취
D('conscious-sedation','의식하진정법','진정·마취','Conscious sedation','의식이 있는 상태에서 진정제로 긴장과 불안을 낮춰 치료받는 방법.','흔히 수면치료, 수면임플란트라고 부르지만 정확한 이름은 의식하진정법입니다. 깨어 있지만 긴장이 풀리고 치료 과정이 잘 기억나지 않는 상태로, 의식을 완전히 잃는 전신마취와 다릅니다.','임플란트·충치·신경·잇몸·보철 치료에 적용할 수 있으며, 건강 상태에 따라 적용 여부를 상담에서 먼저 확인합니다.','의식하진정법 중에 깨어나면 어떻게 하나요?','원래 깨어 있는 상태에서 긴장만 낮추는 방법입니다. 치료 중 상태를 계속 확인하며 조절합니다.',['전신마취와의 차이','치과공포증','국소마취'],'sedation.html',['수면치료','수면임플란트','수면마취']),
D('sedation-vs-ga','전신마취와의 차이','진정·마취','Sedation vs general anesthesia','의식하진정법은 깨어 있고 스스로 숨 쉬는 상태, 전신마취는 의식을 완전히 잃고 호흡을 기계가 돕는 상태.','의식하진정법은 "졸린 상태", 전신마취는 "잠든 상태"에 가깝습니다. 치과 의원에서 하는 것은 의식하진정법입니다.','전신마취가 필요한 경우는 병원급 기관을 안내해 드립니다.','수면치료라고 하면 전신마취인가요?','아닙니다. 치과에서 수면치료라고 부르는 것은 대부분 의식하진정법입니다.',['의식하진정법','치과공포증'],'sedation.html'),
D('local-anesthesia','국소마취','진정·마취','Local anesthesia','치료할 부위 주변에만 마취약을 넣어 그 부분 감각을 없애는 마취.','치과에서 가장 흔한 마취로, 잇몸에 주사해 치료 부위만 감각을 없앱니다. 의식하진정법 중에도 국소마취는 함께 합니다.','주사 전 표면마취를 하고, 통증을 줄이기 위한 방법을 함께 씁니다.','마취는 얼마나 가나요?','부위와 약에 따라 다르며 보통 1~3시간 안팎입니다. 풀리기 전에는 입술이나 볼을 씹지 않도록 주의하세요.',['전달마취','의식하진정법'],'sedation.html'),
D('block-anesthesia','전달마취','진정·마취','Nerve block anesthesia','신경 줄기 쪽에 마취약을 넣어 그 신경이 담당하는 넓은 부위를 마취하는 방법.','아래 어금니처럼 뼈가 두꺼운 곳은 치아 근처만 마취해서는 부족해, 신경이 지나가는 길목에 마취하는 방식입니다.','아래 어금니 치료와 사랑니 발치에서 주로 씁니다.','전달마취 후 입술이 오래 얼얼한데 괜찮나요?','넓은 부위가 마취되어 국소마취보다 오래 갑니다. 대개 몇 시간 안에 풀립니다.',['국소마취','하치조신경','사랑니 발치'],'wisdom.html'),
D('dental-fear','치과공포증','진정·마취','Dental fear','치과 치료에 대한 두려움이 커서 치료를 미루거나 받기 어려운 상태.','어릴 때 아팠던 기억, 주사·기계 소리에 대한 긴장, 구역 반사 등이 원인입니다. 이진학 대표원장도 어렸을 때 치과가 무서웠습니다.','첫 방문에는 검사와 설명까지만 하고 치료는 다음에 하셔도 된다고 말씀드리며, 필요하면 의식하진정법을 안내합니다.','치과가 무서우면 어디서부터 시작하나요?','상담만 받으셔도 됩니다. 설명만 듣고 돌아가셔도 괜찮습니다.',['의식하진정법','국소마취'],'symptom-dental-fear.html'),
D('sedation-prep','진정 전 준비와 보호자 동반','진정·마취','Pre-sedation instructions','의식하진정법 전후로 지켜야 할 식사·복용 약·귀가 방법 안내.','진정 전에는 정해진 시간 동안 음식을 제한하고, 치료 후에는 보호자와 함께 귀가하며 당일 운전은 피합니다.','구체적인 금식 시간과 복용 약 조정은 상담에서 개별적으로 안내드립니다.','진정 후 혼자 집에 가도 되나요?','당일 운전은 피하셔야 하며, 보호자와 함께 귀가하시기를 권합니다.',['의식하진정법','전신마취와의 차이'],'sedation.html'),
# 충치·보존
D('caries','충치(치아우식증)','충치·보존','Dental caries','세균이 만든 산이 치아를 녹여 생기는 병.','입안 세균이 당분을 먹고 산을 만들어 치아 겉면을 조금씩 녹입니다. 초기에는 아프지 않아 정기 검진으로 찾는 것이 중요합니다.','충치 깊이에 따라 레진·인레이·크라운·신경치료 중 맞는 방법을 치과보존과 전문의가 설명드립니다.','충치는 저절로 낫나요?','겉면이 살짝 약해진 초기 단계는 관리로 진행을 늦출 수 있지만, 구멍이 생긴 충치는 저절로 메워지지 않습니다.',['충치 단계','레진','인레이'],'cavity.html'),
D('caries-stages','충치 단계','충치·보존','Stages of caries','충치가 치아 겉면→안쪽→신경→뿌리 끝으로 깊어지는 단계.','겉면(법랑질)에 머문 충치는 작게 메우고, 안쪽(상아질)에 닿으면 시리기 시작하며, 신경에 닿으면 저절로 아파 신경치료가 필요합니다.','엑스레이로 깊이를 확인한 뒤 단계에 맞는 치료를 설명드립니다.','시리지 않으면 충치가 아닌가요?','초기 충치는 아무 느낌이 없습니다. 시리기 시작했다면 이미 안쪽까지 진행된 경우가 많습니다.',['충치','치아 시림','신경치료'],'cavity.html'),
D('sensitivity','치아 시림(지각과민)','충치·보존','Dentin hypersensitivity','찬 것·단 것·칫솔질에 치아가 짧게 찌릿한 증상.','치아 겉면이 닳거나 잇몸이 내려가 안쪽(상아질)이 드러나면, 자극이 신경까지 전달되어 시립니다.','원인(충치·마모·잇몸 퇴축·금)을 확인한 뒤 맞는 처치를 설명드립니다.','시린 치약으로 될까요?','가벼운 시림에는 도움이 되지만 충치나 금이 원인이면 해결되지 않습니다.',['치경부 마모증','잇몸 퇴축','충치'],'symptom-sensitive.html'),
D('resin','레진','충치·보존','Composite resin','치아 색 재료를 충치 자리에 바로 채워 빛으로 굳히는 치료.','본을 뜨지 않고 그 자리에서 메우는 방법으로, 작은 충치나 깨진 부분에 씁니다.','작은 충치에 권하며, 넓은 부위는 인레이나 크라운을 설명드립니다.','레진은 변색되나요?','시간이 지나면 색이 변하거나 가장자리가 닳을 수 있어 정기 점검이 필요합니다.',['인레이','충치','앞니 레진'],'resin.html'),
D('inlay','인레이','충치·보존','Inlay','충치를 제거한 자리의 본을 떠서 맞춤 수복물을 만들어 붙이는 치료.','레진으로 메우기엔 넓고 크라운으로 씌우기엔 아까울 때, 그 자리에 꼭 맞는 조각을 만들어 끼웁니다.','세라믹과 금 중 위치와 씹는 힘에 맞는 재료를 설명드립니다.','인레이는 몇 번 와야 하나요?','보통 본뜨기와 접착, 두 번 안팎입니다.',['온레이','레진','크라운'],'inlay.html'),
D('onlay','온레이','충치·보존','Onlay','인레이보다 범위가 넓어 씹는 면 일부(교두)까지 덮는 수복물.','인레이가 치아 안쪽만 채운다면, 온레이는 씹는 면의 모서리까지 덮어 보호합니다.','남은 치아 양에 따라 인레이·온레이·크라운 중 어느 것이 맞는지 설명드립니다.','온레이와 크라운은 어떻게 다른가요?','온레이는 치아 일부만 덮고, 크라운은 전체를 씌웁니다.',['인레이','크라운'],'inlay.html'),
D('crown','크라운','충치·보존','Dental crown','치아를 다듬고 전체를 씌워 보호하는 보철물.','남은 치아가 적거나 신경치료 후 약해진 치아에 모자처럼 씌워 씹는 힘을 받아 줍니다.','재료별 차이를 설명드리고, 씌운 뒤 맞물림을 여러 번 확인합니다.','크라운을 하면 충치가 안 생기나요?','크라운 자체에는 충치가 안 생기지만 가장자리 치아에는 생길 수 있어 양치와 검진이 필요합니다.',['인레이','신경치료','교합 조정'],'crown.html'),
D('cervical-abrasion','치경부 마모증','충치·보존','Cervical abrasion','치아와 잇몸 경계 부분이 V자로 패이는 것.','센 칫솔질, 이갈이, 산성 음식 등으로 치아 목 부분이 닳아 시리고 음식이 끼기 쉽습니다.','패인 깊이에 따라 레진으로 메우고, 칫솔질 방법을 함께 안내합니다.','패인 곳을 꼭 메워야 하나요?','얕으면 지켜보기도 하고, 시리거나 깊으면 메우기를 권합니다.',['치아 시림','레진','잇몸 퇴축'],'resin.html'),
D('cracked-tooth','치아 균열(크랙)','충치·보존','Cracked tooth','치아에 금이 가서 씹을 때 찌릿하거나 놓을 때 아픈 상태.','딱딱한 음식, 이갈이, 큰 충전물로 치아에 가는 금이 생깁니다. 엑스레이에 잘 안 보여 씹기 검사로 확인합니다.','금의 깊이에 따라 크라운으로 감싸거나 신경치료를 설명드립니다. 두면 금이 깊어질 수 있어 확인을 권합니다.','금 간 치아를 꼭 씌워야 하나요?','금이 더 벌어지지 않게 감싸는 것이 목적이라 대개 크라운을 권합니다.',['크라운','신경치료','씹을 때 아픈 이'],'symptom-pain-chewing.html'),
D('secondary-caries','2차 충치','충치·보존','Secondary caries','예전에 때우거나 씌운 곳의 가장자리에 다시 생기는 충치.','수복물과 치아 사이 틈으로 세균이 들어가 생깁니다. 겉으로 안 보여 엑스레이로 찾는 경우가 많습니다.','오래된 수복물은 정기 검진에서 가장자리를 확인합니다.','때운 곳도 충치가 생기나요?','네. 수복물 가장자리는 충치가 생기기 쉬운 곳입니다.',['충치','인레이','크라운'],'cavity.html'),
# 신경치료
D('root-canal','신경치료(근관치료)','신경치료','Root canal treatment','치아 안의 염증 생긴 신경을 제거하고 그 공간을 채워 치아를 살리는 치료.','치아 속 가는 관(근관)을 청소하고 소독한 뒤 재료로 채웁니다. 여러 번 나눠 진행하며, 끝나면 대개 크라운으로 씌웁니다.','치과보존과 전문의 고수연 원장이 직접 진료합니다. 살리기 어려운 치아는 솔직하게 설명드립니다.','신경치료 중에 안 아프면 그만 와도 되나요?','아닙니다. 중단하면 염증이 재발합니다. 마지막까지 받으셔야 합니다.',['치수','치수염','재신경치료'],'rootcanal.html',['근관치료']),
D('pulp','치수(치아 신경)','신경치료','Dental pulp','치아 안쪽에 있는 신경과 혈관 조직.','치아 가운데 빈 공간에 들어 있는 살아 있는 조직으로, 차가움과 통증을 느끼게 합니다.','충치가 여기까지 닿으면 신경치료가 필요해집니다.','신경을 빼면 치아가 죽나요?','신경은 없어지지만 치아는 뿌리로 뼈에 붙어 계속 쓸 수 있습니다. 다만 약해져 씌우기를 권합니다.',['신경치료','치수염'],'rootcanal.html'),
D('pulpitis','치수염','신경치료','Pulpitis','치아 신경에 생긴 염증.','초기(가역적)에는 자극이 있을 때만 잠깐 아프고, 진행(비가역적)되면 저절로·밤에 더 아픕니다.','진행 정도에 따라 지켜보거나 신경치료를 설명드립니다.','밤에 욱신거리면 무엇인가요?','신경 염증이 진행된 신호인 경우가 많습니다. 빨리 확인을 권합니다.',['치수','신경치료','충치 단계'],'rootcanal.html'),
D('re-rct','재신경치료','신경치료','Endodontic retreatment','예전에 신경치료한 치아에 다시 염증이 생겨 다시 하는 신경치료.','이전에 채운 재료를 걷어 내고 관을 다시 청소·소독한 뒤 채웁니다. 처음보다 까다로운 경우가 많습니다.','치과보존과 전문의가 살릴 수 있는지 먼저 확인하고 설명드립니다.','재신경치료는 성공하나요?','치아 상태에 따라 다르며, 결과를 미리 보장할 수 없습니다. 검사 후 가능성을 설명드립니다.',['신경치료','치근단 농양'],'rootcanal.html'),
D('periapical-abscess','치근단 농양','신경치료','Periapical abscess','치아 뿌리 끝에 고름이 고인 상태.','신경이 죽은 치아 뿌리 끝에 염증이 쌓여 잇몸이 붓거나 고름 주머니가 생깁니다.','신경치료(또는 재신경치료)로 원인을 없애고, 상태에 따라 뿌리 끝 수술을 설명드리기도 합니다.','잇몸에 뾰루지가 났다 없어졌다 하는데요?','뿌리 끝 염증이 터졌다 다시 차는 경우가 많습니다. 저절로 낫는 것이 아니므로 확인을 권합니다.',['신경치료','재신경치료'],'rootcanal.html'),
D('rubber-dam','러버댐','신경치료','Rubber dam','치료할 치아만 드러내고 나머지를 얇은 고무막으로 가리는 장치.','치료 중 침이 들어가지 않게 하고, 기구와 약이 입안으로 가지 않게 보호합니다.','신경치료와 일부 접착 치료에서 사용합니다.','러버댐을 하면 숨쉬기 불편하지 않나요?','코로 숨 쉬면 됩니다. 처음엔 어색하지만 대부분 곧 적응합니다.',['신경치료'],'rootcanal.html'),
# 잇몸
D('gingivitis','치은염','잇몸','Gingivitis','잇몸에만 생긴 초기 염증.','잇몸이 붓고 양치할 때 피가 나는 단계로, 뼈는 아직 괜찮습니다. 스케일링과 양치 교정으로 좋아지는 경우가 많습니다.','스케일링 후 칫솔질 방법을 안내드립니다.','치은염은 낫나요?','원인인 치태·치석을 없애면 대부분 좋아집니다.',['치주염','치석','스케일링'],'gum.html'),
D('periodontitis','치주염(풍치)','잇몸','Periodontitis','염증이 잇몸뼈까지 번져 뼈가 줄어드는 잇몸질환.','치은염이 오래되면 뼈가 녹아 치아가 길어 보이고 흔들립니다. 통증이 적어 늦게 발견되기 쉽습니다.','잇몸 주머니 깊이와 뼈 상태를 보고 잇몸 속 치료를 설명드립니다.','치주염은 완전히 낫나요?','염증은 줄일 수 있지만 녹은 뼈가 돌아오지는 않아, 더 나빠지지 않게 관리하는 것이 목표입니다.',['치은염','치주낭','치근활택술'],'gum.html'),
D('calculus','치석','잇몸','Dental calculus','치태가 굳어 돌처럼 딱딱해진 것.','양치로 안 지워지는 치태가 며칠 지나면 굳어 치석이 됩니다. 표면이 거칠어 세균이 더 잘 붙습니다.','스케일링으로 제거합니다. 잇몸 속 치석은 잇몸치료로 제거합니다.','치석은 집에서 뗄 수 있나요?','칫솔로는 안 떨어집니다. 억지로 긁으면 잇몸이 상할 수 있어 치과에서 제거합니다.',['치태','스케일링','치주염'],'scaling.html'),
D('plaque','치태(플라그)','잇몸','Dental plaque','치아 표면에 붙는 끈적한 세균 막.','하루만 양치를 거르면 느껴지는 미끈한 막입니다. 충치와 잇몸염의 출발점이며 칫솔질로 지울 수 있습니다.','본인 치아에 맞는 칫솔질과 치간 관리법을 안내드립니다.','치태와 치석은 어떻게 다른가요?','치태는 부드러워 양치로 지워지고, 치석은 굳어서 치과에서 떼야 합니다.',['치석','치은염'],'scaling.html'),
D('pocket','치주낭','잇몸','Periodontal pocket','잇몸질환으로 치아와 잇몸 사이가 깊게 벌어진 틈.','건강한 잇몸도 치아와의 사이에 얕은 홈이 있지만, 염증이 진행되면 이 홈이 깊어져 세균이 쌓입니다.','잇몸 검사에서 깊이를 재어 잇몸질환 정도를 판단합니다.','치주낭이 깊으면 어떻게 하나요?','잇몸 속 치료로 염증과 치석을 제거하고, 깊이가 줄지 않으면 추가 치료를 설명드립니다.',['치주염','치근활택술'],'gum.html'),
D('root-planing','치근활택술','잇몸','Root planing','잇몸 속 치아 뿌리 표면의 치석과 염증 조직을 긁어 내고 매끄럽게 하는 치료.','스케일링이 잇몸 위를 청소한다면, 치근활택술은 잇몸 속 뿌리 부분을 청소합니다. 마취 후 부위를 나눠 합니다.','스케일링 후에도 잇몸 속 치석이 남아 있을 때 진행합니다.','치근활택술 후 시린 것은 정상인가요?','뿌리가 드러나 일시적으로 시릴 수 있으며 보통 줄어듭니다.',['치주염','치주낭','스케일링'],'gum.html'),
D('gum-recession','잇몸 퇴축','잇몸','Gingival recession','잇몸이 내려가 치아 뿌리가 드러나는 것.','치아가 길어 보이고 뿌리가 드러나 시리며, 뿌리 충치가 생기기 쉽습니다. 잇몸질환, 센 칫솔질, 이갈이가 원인입니다.','원인을 찾아 관리하고, 시림은 처치로 완화합니다.','내려간 잇몸은 다시 올라오나요?','저절로 돌아오지는 않습니다. 더 내려가지 않게 원인을 관리합니다.',['치아 시림','치경부 마모증','치주염'],'gum.html'),
# 보철·틀니
D('bridge','브릿지','보철·틀니','Dental bridge','빠진 치아 양옆 치아를 다듬어 기둥으로 삼고 그 사이를 잇는 보철.','다리처럼 양옆 치아에 걸쳐 빈 자리를 메웁니다. 임플란트와 달리 옆 치아를 깎아야 합니다.','양옆 치아 상태와 뼈, 비용, 기간을 보고 임플란트와 비교해 설명드립니다.','브릿지와 임플란트 중 뭐가 나은가요?','어느 쪽이 항상 낫다고 할 수 없습니다. 양옆 치아가 건강하면 임플란트를, 치료가 필요하면 브릿지를 고려하기도 합니다.',['임플란트','크라운'],'prosthesis.html'),
D('complete-denture','완전틀니','보철·틀니','Complete denture','치아가 전부 없을 때 잇몸 위에 얹어 쓰는 틀니.','잇몸과 입천장(또는 아래 잇몸)에 밀착해 쓰며, 뺐다 끼웁니다. 만 65세 이상은 조건에 따라 건강보험이 적용됩니다.','적응 기간과 조정 방법을 안내드리고, 흔들림이 크면 오버덴처를 설명드립니다.','틀니는 얼마나 자주 조정하나요?','처음 몇 주는 여러 번 조정이 필요하고, 이후에도 잇몸 변화에 따라 조정합니다.',['부분틀니','오버덴처','틀니 이장'],'denture.html'),
D('partial-denture','부분틀니','보철·틀니','Partial denture','남은 치아에 고리를 걸어 쓰는 틀니.','치아가 일부 남아 있을 때, 남은 치아를 지지대로 삼아 빠진 부분을 채웁니다.','남은 치아 상태가 틀니 수명에 영향을 주므로 함께 관리합니다.','부분틀니 고리가 보이는데 방법이 있나요?','고리 위치와 재료를 바꿔 덜 보이게 설계하기도 합니다. 상담에서 설명드립니다.',['완전틀니','브릿지'],'denture.html'),
D('relining','틀니 이장(리라이닝)','보철·틀니','Denture relining','잇몸이 변해 헐거워진 틀니 안쪽을 다시 맞추는 조정.','틀니는 그대로 두고 잇몸에 닿는 안쪽 면만 새로 채워 다시 밀착시키는 방법입니다.','헐겁거나 아픈 틀니는 참지 마시고 내원해 주세요.','틀니가 헐거우면 새로 해야 하나요?','상태에 따라 이장으로 해결되기도 하고, 오래된 틀니는 재제작을 권하기도 합니다.',['완전틀니','부분틀니'],'denture.html'),
D('occlusal-adjustment','교합 조정','보철·틀니','Occlusal adjustment','치아가 맞물리는 높이와 접촉을 다듬어 고르게 하는 처치.','새 보철이 높거나 특정 치아만 먼저 닿으면 통증·턱 불편이 생깁니다. 닿는 점을 확인해 조금씩 다듬습니다.','바로드림치과의원 시화점은 보철 후 맞물림을 여러 번 나눠 확인합니다.','씌운 치아가 높은 느낌인데 괜찮아지나요?','참지 말고 내원해 조정받으세요. 두면 치아와 턱에 부담이 갑니다.',['크라운','턱관절 장애'],'crown.html'),
# 사랑니·외과
D('impacted-wisdom','매복 사랑니','사랑니·외과','Impacted wisdom tooth','잇몸이나 뼈 속에 묻혀 제대로 나지 못한 사랑니.','자리가 부족해 누워 있거나 묻혀 있어 음식이 끼고 염증·충치가 생기기 쉽습니다.','파노라마(필요시 CT)로 방향과 신경 거리를 확인한 뒤 발치 여부를 설명드립니다.','매복 사랑니는 다 빼야 하나요?','아닙니다. 문제가 반복되거나 앞 치아에 영향을 주면 발치를 권합니다.',['사랑니 발치 후 주의사항','하치조신경','드라이소켓'],'wisdom.html'),
D('dry-socket','드라이소켓','사랑니·외과','Dry socket','발치 후 상처에 피딱지가 제대로 생기지 않아 뼈가 드러나 아픈 상태.','발치 2~4일 뒤 통증이 오히려 심해지면 의심합니다. 빨대 사용, 흡연, 세게 헹구기가 원인이 될 수 있습니다.','발치 당일 주의사항을 안내드리고, 심한 통증이 생기면 바로 내원하시도록 말씀드립니다.','드라이소켓은 어떻게 치료하나요?','상처를 소독하고 약을 넣어 통증을 줄입니다. 며칠에 걸쳐 좋아집니다.',['사랑니 발치 후 주의사항','매복 사랑니'],'wisdom.html'),
D('inferior-alveolar-nerve','하치조신경','사랑니·외과','Inferior alveolar nerve','아래턱 뼈 속을 지나며 아래 치아와 입술·턱 감각을 담당하는 신경.','아래 사랑니 뿌리나 임플란트 자리와 가까울 수 있어, CT로 거리를 확인하는 것이 중요합니다.','신경과 가까우면 미리 설명드리고, 필요하면 네비게이션 임플란트를 고려합니다.','발치 후 입술이 얼얼한 게 안 풀리는데요?','신경 가까이에서 발치하면 일시적으로 감각이 둔해질 수 있습니다. 대부분 회복되지만 기간은 개인차가 있어 경과를 확인합니다.',['매복 사랑니','CT 검사','전달마취'],'wisdom.html'),
D('post-extraction','발치 후 주의사항','사랑니·외과','Post-extraction care','발치 뒤 피를 멎게 하고 상처가 잘 아물도록 지켜야 할 것들.','거즈를 물고 지혈하고, 당일에는 빨대·흡연·음주·격한 운동을 피하며, 세게 헹구지 않습니다.','발치 후 안내문을 드리고, 며칠 뒤 경과를 확인합니다.','발치 후 양치는 언제부터 하나요?','발치 자리를 피해 당일부터 조심스럽게 하실 수 있습니다. 상처 부위는 며칠 뒤부터 부드럽게 닦습니다.',['드라이소켓','매복 사랑니'],'wisdom.html'),
# 예방
D('scaling','스케일링','예방','Scaling','치아에 붙은 치석과 치태를 기구로 제거하는 처치.','잇몸질환 예방의 기본으로, 만 19세 이상은 1년에 한 번 건강보험이 적용됩니다.','치석 양과 잇몸 상태를 보고 필요하면 잇몸 속 치료를 함께 설명드립니다.','스케일링 후 치아 사이가 벌어졌어요.','치석이 빠진 자리가 비어 보이는 것이며 치아가 깎인 것은 아닙니다.',['치석','치은염','치근활택술'],'scaling.html'),
D('fluoride','불소 도포','예방','Fluoride application','치아 표면에 불소를 발라 충치 저항력을 높이는 예방 처치.','불소는 치아 겉면을 단단하게 하고 초기 충치의 진행을 늦추는 데 도움이 됩니다. 아이와 충치가 잘 생기는 성인에게 씁니다.','정기 검진 때 필요 여부를 안내드립니다.','불소 도포 후 바로 먹어도 되나요?','보통 30분 정도 음식과 양치를 피하도록 안내합니다.',['충치','치아 홈메우기'],'cavity.html'),
D('sealant','치아 홈메우기(실란트)','예방','Pit and fissure sealant','어금니 씹는 면의 깊은 홈을 미리 메워 충치를 예방하는 처치.','음식이 끼기 쉬운 어금니 홈을 얇은 재료로 덮어 세균이 쌓이지 않게 합니다. 아이의 영구치 어금니에 주로 합니다.','만 18세 이하 영구치 어금니는 조건에 따라 건강보험이 적용됩니다.','실란트는 한 번 하면 끝인가요?','닳거나 떨어질 수 있어 검진 때 확인하고 필요하면 다시 합니다.',['충치','불소 도포'],'cavity.html'),
# 턱관절
D('tmd','턱관절 장애','턱관절','Temporomandibular disorder','턱관절과 주변 근육에 문제가 생겨 소리·통증·개구 제한이 나타나는 상태.','입을 벌릴 때 딱 소리, 턱 통증, 입이 잘 안 벌어지는 증상이 대표적입니다. 습관과 스트레스의 영향이 큽니다.','습관 교정, 장치 치료, 약물·물리치료를 단계적으로 설명드립니다.','턱 소리만 나는데 치료해야 하나요?','통증·걸림이 없으면 지켜보며 습관을 관리하기도 합니다.',['교합안정장치','교합 조정'],'tmj.html'),
D('splint','교합안정장치(스플린트)','턱관절','Occlusal splint','턱관절과 근육의 부담을 줄이기 위해 치아에 끼는 맞춤 장치.','주로 밤에 끼는 투명한 틀로, 이갈이·이 악물기의 힘을 분산하고 턱관절을 쉬게 합니다.','증상에 따라 제작하고 정기적으로 조정합니다.','장치는 얼마나 끼나요?','보통 밤에 끼며 기간은 증상에 따라 다릅니다.',['턱관절 장애'],'tmj.html'),
]

CATS = ['임플란트','풀아치·틀니','진정·마취','충치·보존','신경치료','잇몸','보철·틀니','사랑니·외과','예방','턱관절']
BY_TERM = {t['term']: t for t in TERMS}

def term_link(name):
    t = BY_TERM.get(name)
    return f'<a href="dictionary/{t["slug"]}.html">{esc(name)}</a>' if t else esc(name)

def render_term(t, site, page_hero, ld_breadcrumb, ld_faq, faq_html, ld_medpage, doctor_names, site_url):
    file = f'dictionary/{t["slug"]}.html'
    crumbs=[('홈','index.html'),('치과 용어사전','dictionary/index.html'),(t['term'], file)]
    rel = ' '.join(f'<a href="dictionary/{BY_TERM[r]["slug"]}.html">{esc(r)}</a>' for r in t['rel'] if r in BY_TERM)
    page_link = f'<p style="margin-top:24px"><a class="btn btn-s btn-sm" href="{t["page"]}">관련 진료 안내 보기</a></p>' if t.get('page') else ''
    body = page_hero(dict(h1=t['term'], lead=t['one']), crumbs) + f'''
<section class="sec"><div class="wrap prose">
  <p class="caption">{esc(t['cat'])} · {esc(t['en'])}</p>
  <h2>쉽게 말하면</h2><p>{t['easy']}</p>
  <h2>바로드림치과의원 시화점에서는</h2><p>{t['here']}</p>
  <h2>관련 용어</h2><div class="related">{rel}</div>
  {page_link}
  <p class="small muted" style="margin-top:24px">용어 설명은 일반적인 내용이며 진단을 대신하지 않습니다. 치료 방법과 결과는 개인의 상태에 따라 다릅니다.</p>
  <div class="tx-meta"><span>작성 {esc(site['name'])}</span><span>검토 {doctor_names['lee'] if t['cat'] in ('임플란트','풀아치·틀니','진정·마취','보철·틀니','사랑니·외과','턱관절') else doctor_names['ko']}</span></div>
</div></section>''' + faq_html([t['faq']])
    page = dict(file=file, h1=t['term'], title=f'{t["term"]}이란? 뜻과 쉬운 설명 | 바로드림치과의원 시화점 치과 용어사전',
                description=f'{t["term"]}: {t["one"]} {t["easy"][:70]}…', ai_summary=f'{t["term"]}({t["en"]}): {t["one"]}')
    ld_term = {"@context":"https://schema.org","@type":"DefinedTerm","name":t['term'],"description":t['one'],"inDefinedTermSet":{"@type":"DefinedTermSet","name":"바로드림치과의원 시화점 치과 용어사전","url":f"{site_url}/dictionary/"},"url":f"{site_url}/{file}"}
    if t['aliases']: ld_term['alternateName'] = t['aliases']
    return dict(page=page, body=body, ld=[ld_breadcrumb(crumbs), ld_term, ld_faq([t['faq']])], prio='0.6')

def render_index(site, page_hero, ld_breadcrumb):
    file='dictionary/index.html'
    crumbs=[('홈','index.html'),('치과 용어사전', file)]
    sections=''
    for c in CATS:
        items=[t for t in TERMS if t['cat']==c]
        if not items: continue
        sections += f'<h2 id="{esc(c)}" style="margin:40px 0 12px;font-size:22px">{esc(c)}</h2><div class="dir" style="columns:2;column-gap:32px">' + ''.join(f'<a href="dictionary/{t["slug"]}.html" style="break-inside:avoid"><b style="font-weight:600">{esc(t["term"])}</b> <span class="small muted">— {esc(t["one"][:38])}…</span></a>' for t in items) + '</div>'
    nav=' '.join(f'<a href="#{esc(c)}">{esc(c)}</a>' for c in CATS)
    page=dict(file=file, h1='치과 용어사전', title='치과 용어사전 — 임플란트·의식하진정법·신경치료·잇몸 용어 쉽게 설명 | 바로드림치과의원 시화점',
              description=f'치과에서 듣는 말을 쉽게 풀어 쓴 용어사전 {len(TERMS)}개. 임플란트, 픽스처, 골유착, 의식하진정법, 신경치료, 치주염, 틀니, 사랑니, 턱관절까지. 바로드림치과의원 시화점.',
              lead='진료실에서 듣는 말을 쉽게 풀어 썼습니다. 모르는 단어가 있으면 상담 때 그대로 물어보셔도 됩니다.')
    body = page_hero(page, crumbs) + f'<section class="sec"><div class="wrap"><div class="related" style="margin-bottom:8px">{nav}</div>{sections}<p class="caption" style="margin-top:32px">용어는 계속 추가됩니다. 현재 {len(TERMS)}개.</p></div></section>'
    ld_set={"@context":"https://schema.org","@type":"DefinedTermSet","name":"바로드림치과의원 시화점 치과 용어사전","hasDefinedTerm":[{"@type":"DefinedTerm","name":t['term'],"url":f"{{SITE_URL}}/dictionary/{t['slug']}.html"} for t in TERMS]}
    return dict(page=page, body=body, ld=[ld_breadcrumb(crumbs), ld_set], prio='0.7')
